class Solution {
  public int[] subarrayMajority(int[] nums, int[][] queries) {
    int n = nums.length, q = queries.length;
    int[] sorted = nums.clone();
    java.util.Arrays.sort(sorted);
    int m = 0;
    for (int i = 0; i < n; i++) if (i == 0 || sorted[i] != sorted[i - 1]) sorted[m++] = sorted[i];
    int[] id = new int[n];
    for (int i = 0; i < n; i++) id[i] = java.util.Arrays.binarySearch(sorted, 0, m, nums[i]);
    int words = (m + 63) / 64;
    long[][] level = new long[n + 2][];
    int[] levelCount = new int[n + 2], freq = new int[m];
    int block = Math.max(1, (int) (n / Math.sqrt(q) + 1));
    Integer[] order = new Integer[q];
    for (int i = 0; i < q; i++) order[i] = i;
    java.util.Arrays.sort(
        order,
        (a, b) -> {
          int ba = queries[a][0] / block, bb = queries[b][0] / block;
          if (ba != bb) return Integer.compare(ba, bb);
          return (ba & 1) == 0
              ? Integer.compare(queries[a][1], queries[b][1])
              : Integer.compare(queries[b][1], queries[a][1]);
        });
    int[] ans = new int[q];
    int curL = 0, curR = -1, mx = 0;
    for (int qi : order) {
      int l = queries[qi][0], r = queries[qi][1];
      while (curL > l) {
        curL--;
        mx = add(id[curL], freq, level, levelCount, words, mx);
      }
      while (curR < r) {
        curR++;
        mx = add(id[curR], freq, level, levelCount, words, mx);
      }
      while (curL < l) {
        mx = remove(id[curL], freq, level, levelCount, mx);
        curL++;
      }
      while (curR > r) {
        mx = remove(id[curR], freq, level, levelCount, mx);
        curR--;
      }
      int res = -1;
      if (mx >= queries[qi][2]) {
        long[] bits = level[mx];
        for (int w = 0; w < words; w++) {
          if (bits[w] != 0) {
            res = sorted[w * 64 + Long.numberOfTrailingZeros(bits[w])];
            break;
          }
        }
      }
      ans[qi] = res;
    }
    return ans;
  }

  private static int add(int v, int[] freq, long[][] level, int[] levelCount, int words, int mx) {
    int f = freq[v];
    if (f > 0) {
      level[f][v >> 6] &= ~(1L << (v & 63));
      levelCount[f]--;
    }
    f++;
    freq[v] = f;
    if (level[f] == null) level[f] = new long[words];
    level[f][v >> 6] |= 1L << (v & 63);
    levelCount[f]++;
    return Math.max(mx, f);
  }

  private static int remove(int v, int[] freq, long[][] level, int[] levelCount, int mx) {
    int f = freq[v];
    level[f][v >> 6] &= ~(1L << (v & 63));
    levelCount[f]--;
    f--;
    freq[v] = f;
    if (f > 0) {
      level[f][v >> 6] |= 1L << (v & 63);
      levelCount[f]++;
    }
    if (levelCount[mx] == 0 && mx > 0) mx--;
    return mx;
  }
}
